import hotspots from "../../public/model/hotspots.json";
import type { RoomKey } from "../data/portfolio";

// Everything here is generated by model/export_web_layers.py.
export type Spot = { polygon: number[][]; focus: number[]; plan: number[][] };

export const model = {
  version: hotspots.version,
  width: hotspots.width,
  height: hotspots.height,
  plinthAspect: hotspots.plinthAspect,
  spots: hotspots.buildings as Record<RoomKey, Spot>,
};

// Cache-buster: changes on every Blender export, so visitors always get fresh renders.
export const modelSrc = (file: string) => `/model/${file}?v=${model.version}`;
